{
  "claims": [
    {
      "claim_text": "Strings and BLOBs are capped at 1 billion bytes by default (SQLITE_MAX_LENGTH).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states the default value of SQLITE_MAX_LENGTH is 1 billion bytes.",
      "citations": [
        {"index": 0, "quote": "The default value of this macro is 1 billion (1 thousand million or 1,000,000,000)."}
      ]
    },
    {
      "claim_text": "Tables can have at most 2000 columns by default (SQLITE_MAX_COLUMN).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 states the default setting for SQLITE_MAX_COLUMN is 2000.",
      "citations": [
        {"index": 1, "quote": "The default setting for SQLITE_MAX_COLUMN is 2000."}
      ]
    },
    {
      "claim_text": "Well-normalized schemas rarely need more than about 100 columns.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 says experienced designers argue a well-normalized database will never need more than 100 columns.",
      "citations": [
        {"index": 1, "quote": "many experienced database designers will argue that a well-normalized database will never need more than 100 columns in a table."}
      ]
    },
    {
      "claim_text": "Queries with joins are limited to 64 tables.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 states SQLite does not support joins containing more than 64 tables.",
      "citations": [
        {"index": 2, "quote": "SQLite does not support joins containing more than 64 tables."}
      ]
    },
    {
      "claim_text": "The join limit cannot be raised or lowered because the query planner uses one-bit-per-table bitmaps internally.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 3 says there is no mechanism to raise or lower the join limit; passage 2 says the limit arises from bitmaps with one bit per join-table.",
      "citations": [
        {"index": 3, "quote": "Hence, there is no mechanism to raise or lower the limit on the number of tables in a join."},
        {"index": 2, "quote": "This limit arises from the fact that the SQLite code generator uses bitmaps with one bit per join-table in the query optimizer."}
      ]
    },
    {
      "claim_text": "Expression trees can nest up to 1000 levels deep by default (SQLITE_MAX_EXPR_DEPTH).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 states the current implementation has a default value of 1000 for SQLITE_MAX_EXPR_DEPTH.",
      "citations": [
        {"index": 4, "quote": "The current implementation has a default value of 1000."}
      ]
    },
    {
      "claim_text": "For SQLITE_MAX_EXPR_DEPTH, a value of 0 means unlimited.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 4 states if the value is 0, then no limit is enforced.",
      "citations": [
        {"index": 4, "quote": "If the value is 0, then no limit is enforced."}
      ]
    },
    {
      "claim_text": "Compound SELECT statements can have at most 500 terms by default (SQLITE_MAX_COMPOUND_SELECT).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 states the maximum number of terms is SQLITE_MAX_COMPOUND_SELECT which defaults to 500.",
      "citations": [
        {"index": 5, "quote": "The maximum number of terms is SQLITE_MAX_COMPOUND_SELECT which defaults to 500."}
      ]
    },
    {
      "claim_text": "The 500-term compound SELECT limit is generous since real-world compound selects almost never exceed single digits.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 says they think this is a generous allotment since in practice the number of terms almost never exceeds single digits.",
      "citations": [
        {"index": 5, "quote": "We think this is a generous allotment since in practice we almost never see the number of terms in a compound select exceed single digits."}
      ]
    },
    {
      "claim_text": "Host parameter numbers are limited to 999 in versions before 3.32.0 and 32766 in later versions.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states SQLITE_MAX_VARIABLE_NUMBER defaults to 999 for versions prior to 3.32.0 or 32766 for versions after 3.32.0.",
      "citations": [
        {"index": 6, "quote": "which defaults to 999 for SQLite versions prior to 3.32.0 (2020-05-22) or 32766 for SQLite versions after 3.32.0."}
      ]
    },
    {
      "claim_text": "SQLite allocates space for every host parameter between 1 and the highest number used.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 states SQLite allocates space to hold all host parameters between 1 and the largest host parameter number used.",
      "citations": [
        {"index": 6, "quote": "SQLite allocates space to hold all host parameters between 1 and the largest host parameter number used."}
      ]
    },
    {
      "claim_text": "A stray ?1000000000 could demand gigabytes of memory.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 says an SQL statement with a host parameter like ?1000000000 would require gigabytes of storage.",
      "citations": [
        {"index": 6, "quote": "an SQL statement that contains a host parameter like ?1000000000 would require gigabytes of storage."}
      ]
    },
    {
      "claim_text": "You can ATTACH up to 10 databases to a single connection by default (SQLITE_MAX_ATTACHED).",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states the number of simultaneously attached databases is limited to SQLITE_MAX_ATTACHED which is set to 10 by default.",
      "citations": [
        {"index": 7, "quote": "The number of simultaneously attached databases is limited to SQLITE_MAX_ATTACHED which is set to 10 by default."}
      ]
    },
    {
      "claim_text": "The maximum number of attached databases has a hard ceiling of 125.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 states the maximum number of attached databases cannot be increased above 125.",
      "citations": [
        {"index": 7, "quote": "The maximum number of attached databases cannot be increased above 125."}
      ]
    },
    {
      "claim_text": "SQLITE_MAX_PAGE_COUNT defaults to 4294967294 pages since version 3.45.0.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states since version 3.45.0, 4294967294 is also the default value for SQLITE_MAX_PAGE_COUNT.",
      "citations": [
        {"index": 8, "quote": "Since version 3.45.0 (2024-01-15), 4294967294 is also the default value for SQLITE_MAX_PAGE_COUNT."}
      ]
    },
    {
      "claim_text": "With the default 4096-byte page size, the maximum database size is roughly 17.5 terabytes.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states with the default page size of 4096 bytes, this gives a maximum database size of about 17.5 terabytes.",
      "citations": [
        {"index": 8, "quote": "When used with the default page size of 4096 bytes, this gives a maximum database size of about 17.5 terabytes."}
      ]
    },
    {
      "claim_text": "With the maximum 65536-byte page size, the database file can grow to about 281 terabytes.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 8 states if the page size is increased to the maximum of 65536 bytes, the database file can grow to be as large as about 281 terabytes.",
      "citations": [
        {"index": 8, "quote": "If the page size is increased to the maximum of 65536 bytes, then the database file can grow to be as large as about 281 terabytes."}
      ]
    },
    {
      "claim_text": "Most of these limits (except the join limit) can be adjusted at compile time if your workload genuinely requires it.",
      "verdict": "UNSUPPORTED",
      "reasoning": "The passages state compile-time adjustability for some limits (SQLITE_MAX_LENGTH, SQLITE_MAX_COLUMN, SQLITE_MAX_EXPR_DEPTH implicitly via parameter, SQLITE_MAX_VARIABLE_NUMBER, SQLITE_MAX_ATTACHED up to 125) and explicitly say the join limit cannot be changed, but they do not state that 'most' limits except the join limit can be adjusted at compile time. In particular, SQLITE_MAX_COMPOUND_SELECT and SQLITE_MAX_PAGE_COUNT adjustability is not stated, and the blanket claim is not entailed.",
      "citations": []
    }
  ]
}
